def f2(g):
    H,W=len(g),len(g[0])
    cs=comps8(g)
    res=[r[:] for r in g]
    for i,A in enumerate(cs):
        for B in cs[i+1:]:
            rsA=[p[0] for p in A]; ccA=[p[1] for p in A]
            rsB=[p[0] for p in B]; ccB=[p[1] for p in B]
            r0A,r1A=min(rsA),max(rsA); c0A,c1A=min(ccA),max(ccA)
            r0B,r1B=min(rsB),max(rsB); c0B,c1B=min(ccB),max(ccB)
            hbr = (r1A>=r0B and r1B>=r0A)   # row bands overlap
            vbr = (c1A>=c0B and c1B>=c0A)
            if hbr and not vbr:
                # horizontal bridge: find A-cell with max col (rightmost) and B-cell with min col
                ca=max(A,key=lambda p:p[1]); cb=min(B,key=lambda p:p[1])
                for c in range(ca[1]+1,cb[1]): res[ca[0]][c]=1
            elif vbr and not hbr:
                ra=max(A,key=lambda p:p[0]); rb=min(B,key=lambda p:p[0])
                for r in range(ra[0]+1,rb[0]): res[r][ra[1]]=1
            elif hbr and vbr:
                # ambiguous: use whichever gap is shorter
                ca=max(A,key=lambda p:p[1]); cb=min(B,key=lambda p:p[1])
                ra=max(A,key=lambda p:p[0]); rb=min(B,key=lambda p:p[0])
                dh=cb[1]-ca[1]-1; dv=rb[0]-ra[0]-1
                if dh<=dv:
                    for c in range(ca[1]+1,cb[1]): res[ca[0]][c]=1
                else:
                    for r in range(ra[0]+1,rb[0]): res[r][ra[1]]=1
    return res

