def f(g):
    H,W=len(g),len(g[0]); cs=comps(g,8); lab={pos:k for k,c in enumerate(cs) for pos in c}
    res=[r[:] for r in g]
    def faces(a,b,dr,dc):
        for dy in(-1,0,1):
            for dx in(-1,0,1):
                n=(a[0]+dy,a[1]+dx)
                if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]==2:
                    # facing: projection onto line direction aligns with dc
                    if dc* (n[1]-b[1]) >=0 and abs(dc*(n[1]-b[1])) >= abs(dy*0): pass
                    return True if (n[1]-a[1])*dc>=0 and ((abs(n[1]-a[1])+abs(n[0]-a[0]))<=1 else False)
        return False
    def ff(a,b):
        n=a[0];m=b[0]
        da=n-a[1];db=m-b[1]
        return (da>0)==(db<0) or (da<0)==(db>0)
    for r in range(H):
        pts=sorted(c for c in range(W) if g[r][c]==2)
        for aa,bb in zip(pts,pts[1:]):
            gap=bb-aa-1
            if gap>4: continue
            fa=faces((r,aa),(r,bb),1,0)
            fb=faces((r,bb),(r,aa),-1,0)
            if (fa or fb) and lab[(r,aa)]!=lab[(r,bb)]:
                for z in range(aa+1,bb): res[r][z]=1
    for c in range(W):
        pts=sorted(r for r in range(H) if g[r][c]==2)
        for aa,bb in zip(pts,pts[1:]):
            gap=bb-aa-1
            if gap>4: continue
            fa=faces((aa,c),(bb,c),0,1)
            fb=faces((bb,c),(aa,c),0,-1)
            if (fa or fb) and lab[(aa,c)]!=lab[(bb,c)]:
                for z in range(aa+1,bb): res[z][c]=1
    return res

