def f(g):
    H,W=len(g),len(g[0]); cs=comps(g,8); lab={pos:k for k,c in enumerate(cs) for pos in c}
    res=[r[:] for r in g]
    def has(a,b):
        dr=sign(b[0]-a[0]);dc=sign(b[1]-a[1])
        return any(g[a[0]+dr*dy*a_sign][a[1]+dc*dx*b_sign]==2
                   for dy in(-1,0,1) for dx in(-1,0,1)
                   for a_sign in (-1,1) if a_sign==dr or (dr==0 and a_sign==0)
                   for b_sign in (-1,1) if b_sign==-dc or (dc==0 and b_sign==0))
        # cleaner: neighbors within 1 step, where dx has sign -dc? neighbor n should be between: (n-a) dot d <0 where d=d_b-a
        d=b[0]-a[0],b[1]-a[1]
        return any((n[0]-a[0])*d[0]+(n[1]-a[1])*d[1]<0
                    for n in [(a[0]+dy,a[1]+dx) for dy in(-1,0,1) for dx in(-1,0,1)]
                    if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]==2)
    for r in range(H):
        pts=sorted(c for c in range(W) if g[r][c]==2)
        for aa,bb in zip(pts,pts[1:]):
            if bb-aa-1>4 or lab[(r,aa)]==lab[(r,bb)]: continue
            for a,b in ((r,aa),(r,bb)):
                if has(a,b):
                    for z in range(aa+1,bb): res[r][z]=1; break
    for c in range(W):
        pts=sorted(r for r in range(H) if g[r][c]==2)
        for aa,bb in zip(pts,pts[1:]):
            if bb-aa-1>4 or lab[(aa,c)]==lab[(bb,c)]: continue
            for a,b in ((aa,c),(bb,c)):
                if has(a,b):
                    for z in range(aa+1,bb): res[z][c]=1; break
    return res
