def f(g):
    g=[r[:] for r in g]
    cs=comps(g)
    clusters=[set(c) for c in cs]
    res=[r[:] for r in g]
    # cluster center
    def cr(cl):
        s=[p for p in cl]
        return (sum(p[0] for p in s)/len(s), sum(p[1] for p in s)/len(s))
    clrs=[cr(cl) for cl in clusters]
    for i in range(len(clusters)):
        for j in range(i+1,len(clusters)):
            ca,cb=clrs[i],clrs[j]
            if abs(ca[0]-cb[0])<1e-9 or abs(ca[1]-cb[1])<1e-9:
                # vertical bridge if row same else horizontal
                if abs(ca[0]-cb[0])<1e-9:
                    # horizontal: sort by col
                    o1,o2=sorted([clusters[i],clusters[j]],key=lambda cl:min(p[1] for p in cl))
                    # endpoint cells: from o1 pick max col cell; from o2 pick min col cell
                    ea=max(o1,key=lambda p:p[1]); eb=min(o2,key=lambda p:p[1])
                    for c in range(ea[1]+1,eb[1]): res[ea[0]][c]=1
                else:
                    o1,o2=sorted([clusters[i],clusters[j]],key=lambda cl:min(p[0] for p in cl))
                    ea=max(o1,key=lambda p:p[0]); eb=min(o2,key=lambda p:p[0])
                    for r in range(ea[0]+1,eb[0]): res[r][eb[1]]=1
    return res

